1	package nexusfixture_test
2	
3	import (
4		"os"
5		"path/filepath"
6		"sort"
7		"strings"
8		"testing"
9	
10		"github.com/anthnel/devdesk/internal/nexusfixture"
11	)
12	
13	// A campaign is written as request-only "record: pending" files before the
14	// recorder fills them (NX-04, DEVDESK-580 PR3). Load refuses such a file on
15	// purpose, so a campaign that still holds one cannot be replayed, loaded by
16	// All() or checked for provenance: those checks cover the campaigns that are
17	// fully recorded, and the pending files are still checked for leaks and for
18	// the round trip, which read the files themselves. A campaign leaves this
19	// state by itself, as soon as the recorder has written its last file.
20	
21	// pendingFiles lists, per campaign, the fixture files on disk that still say
22	// "record: pending", sorted. A campaign with none is absent.
23	func pendingFiles(t *testing.T) map[string][]string {
24		t.Helper()
25		pending := map[string][]string{}
26		for _, campaign := range nexusfixture.Campaigns() {
27			files, err := filepath.Glob(filepath.Join("fixtures", campaign, "*.http"))
28			if err != nil {
29				t.Fatal(err)
30			}
31			for _, file := range files {
32				data, err := os.ReadFile(file)
33				if err != nil {
34					t.Fatal(err)
35				}
36				f, err := nexusfixture.Parse(campaign, filepath.Base(file), data)
37				if err != nil {
38					t.Fatalf("Parse(%s): %v", file, err)
39				}
40				if f.Meta.Record == nexusfixture.RecordPending {
41					pending[campaign] = append(pending[campaign], strings.TrimSuffix(filepath.Base(file), ".http"))
42				}
43			}
44			sort.Strings(pending[campaign])
45		}
46		return pending
47	}
48	
49	func countPending(pending map[string][]string) int {
50		n := 0
51		for _, names := range pending {
52			n += len(names)
53		}
54		return n
55	}
56	
57	// loadableCampaigns is Campaigns() without the campaigns that still hold a pending file.
58	func loadableCampaigns(t *testing.T) []string {
59		t.Helper()
60		pending := pendingFiles(t)
61		var campaigns []string
62		for _, c := range nexusfixture.Campaigns() {
63			if len(pending[c]) == 0 {
64				campaigns = append(campaigns, c)
65			} else {
66				t.Logf("campaign %s is skipped: %d fixture(s) still pending, e.g. %s", c, len(pending[c]), pending[c][0])
67			}
68		}
69		return campaigns
70	}
71	
72	// loadAllRecorded is All() over the loadable campaigns.
73	func loadAllRecorded(t *testing.T) []nexusfixture.Fixture {
74		t.Helper()
75		var all []nexusfixture.Fixture
76		for _, c := range loadableCampaigns(t) {
77			fixtures, err := nexusfixture.Load(c)
78			if err != nil {
79				t.Fatalf("Load(%s): %v", c, err)
80			}
81			all = append(all, fixtures...)
82		}
83		return all
84	}
85	
86	// While a campaign holds a pending file, All() fails and names it: nothing
87	// replays a request that has no answer.
88	func TestAllRefusesACampaignWithAPendingFixture(t *testing.T) {
89		pending := pendingFiles(t)
90		if len(pending) == 0 {
91			t.Skip("no pending fixture: every campaign is recorded")
92		}
93		_, err := nexusfixture.All()
94		if err == nil {
95			t.Fatalf("All() = nil error with pending fixtures %v, want an error", pending)
96		}
97		if !strings.Contains(strings.ToLower(err.Error()), "pending") {
98			t.Errorf("All() error %q does not say a fixture is pending", err)
99		}
100	}
101

